      txt(bc, (u.req && !s.built[u.req] ? 'Bouw eerst: ' + BUILD[u.req].name : u.cost + ' goud  ·  voorraad ' + s.stock[id]), 14, y + 25, 11, '#9aa1b5');
      button('Koop', 244, y + 3, 62, 28, () => Rules.recruit(id), s.stock[id] > 0 && s.gold >= u.cost && !(u.req && !s.built[u.req]));
      y += 38;
