const VAR = { gobarcher: { b: 'goblin', col: 'rgba(255,205,30,.36)', k: 1 }, direwolf: { b: 'wolf', col: 'rgba(255,60,30,.4)', k: 1.2 }, warlord: { b: 'ogre', col: 'rgba(140,70,255,.4)', k: 1.3 } };
