      try { _sp8(c, id, side, cx, cy2, R2); } finally { if (had) IM[id] = sv; else delete IM[id]; }
      if (id === 'gobarcher') { const dir = side ? -1 : 1; c.save(); c.strokeStyle = '#6a3a10'; c.lineWidth = Math.max(1, R * .12); c.beginPath(); c.arc(cx + dir * R * .55, cy2 - R * .1, R * .55, dir > 0 ? -1.2 : Math.PI - 1.2, dir > 0 ? 1.2 : Math.PI + 1.2); c.stroke(); c.restore(); }
